{"path": "src/sample/embedder.py", "content": "import os
from typing import List
import openai
from .config import OPENAI_API_KEY, OPENAI_EMBEDDING_MODEL, EMBEDDING_DIMS

if OPENAI_API_KEY:
    openai.api_key = OPENAI_API_KEY


def embed_text(text: str) -> List[float]:
    """Call OpenAI embeddings API and return a vector."""
    if not OPENAI_API_KEY:
        raise RuntimeError("OPENAI_API_KEY not set")
    resp = openai.Embedding.create(model=OPENAI_EMBEDDING_MODEL, input=text)
    vec = resp["data"][0]["embedding"]
    if len(vec) != EMBEDDING_DIMS:
        # warn but still return
        print(f"Warning: embedding dim {len(vec)} != expected {EMBEDDING_DIMS}")
    return vec


def embed_features_as_text(features: list) -> List[float]:
    # For simplicity, we stringify the features into a stable text representation
    # and embed that.
    text = "features:" + ",".join([f"{x:.6f}" for x in features])
    return embed_text(text)
"}

{"path": "src/sample/create_indexes.py", "content": """"Create a vector index on employee_vectors.embedding using the cosmosSearch pattern.

This script uses the MongoDB runCommand 'createIndexes' with cosmosSearchOptions as required by Azure DocumentDB.

Usage: python -m sample.create_indexes
"""
from sample.db import get_db
from sample.config import EMBEDDING_DIMS


def create_vector_index():
    db = get_db()
    coll_name = "employee_vectors"
    # ensure collection exists
    if coll_name not in db.list_collection_names():
        db.create_collection(coll_name)
    # build createIndexes command payload
    indexes = [
        {
            "key": {"embedding": "cosmosSearch"},
            "name": "embedding_vector_ivf",
            "cosmosSearchOptions": {
                "kind": "vector-ivf",
                "dimensions": EMBEDDING_DIMS,
                "similarity": "COS",
                "algorithmParameters": {"nlist": 1024}
            }
        }
    ]
    try:
        res = db.command({"createIndexes": coll_name, "indexes": indexes})
        print("createIndexes result:", res)
    except Exception as e:
        print("Error creating vector index:", e)


if __name__ == "__main__":
    create_vector_index()
"}

